1	import type { AgentSessionEvent } from "@earendil-works/pi-coding-agent";
2	
3	import type {
4	  AguiEvent,
5	  PiMapperContext,
6	  PiMappableEvent,
7	  SheafActivity,
8	  UserMessageAguiInput,
9	} from "./types.js";
10	import { SanitizeOptions, SanitizeValue } from "./sanitizer.js";
11	
12	interface OpenToolCall
13	{
14	  toolCallId: string;
15	  toolCallName: string;
16	  parentMessageId?: string;
17	}
18	
19	function IsRecord(value: unknown): value is Record<string, unknown>
20	{
21	  return typeof value === "object" && value !== null && !Array.isArray(value);
22	}
23	
24	function StringifyPayload(value: unknown): string
25	{
26	  if (typeof value === "string")
27	  {
28	    return value;
29	  }
30	
31	  if (IsRecord(value))
32	  {
33	    const sorted: Record<string, unknown> = {};
34	
35	    for (const key of Object.keys(value).sort())
36	    {
37	      sorted[key] = value[key];
38	    }
39	
40	    return JSON.stringify(sorted);
41	  }
42	
43	  return JSON.stringify(value);
44	}
45	
46	export class PiToAguiMapper
47	{
48	  private m_fallbackEvents: Record<string, unknown>[] = [];
49	  private m_openRuns = new Set<string>();
50	  private m_openTextMessages = new Set<string>();
51	  private m_openReasoningMessages = new Set<string>();
52	  private m_openReasoningPhases = new Set<string>();
53	  private m_openTools = new Map<string, OpenToolCall>();
54	  private m_seenTools = new Set<string>();
55	  private m_toolsWithArgs = new Set<string>();
56	  private m_runCounter = 0;
57	
58	  Reset(): void
59	  {
60	    this.m_fallbackEvents = [];
61	    this.m_openRuns.clear();
62	    this.m_openTextMessages.clear();
63	    this.m_openReasoningMessages.clear();
64	    this.m_openReasoningPhases.clear();
65	    this.m_openTools.clear();
66	    this.m_seenTools.clear();
67	    this.m_toolsWithArgs.clear();
68	    this.m_runCounter = 0;
69	  }
70	
71	  Errors(): Record<string, unknown>[]
72	  {
73	    return this.m_fallbackEvents.map((event) => structuredClone(event));
74	  }
75	
76	  Consume(event: PiMappableEvent, context: PiMapperContext): AguiEvent[]
77	  {
78	    try
79	    {
80	      return this.MapEvent(event, context);
81	    }
82	    catch
83	    {
84	      return this.Fallback(event, context);
85	    }
86	  }
87	
88	  MapEvent(event: PiMappableEvent, context: PiMapperContext): AguiEvent[]
89	  {
90	    if (!IsRecord(event) || typeof event.type !== "string")
91	    {
92	      return this.Fallback(event, context);
93	    }
94	
95	    const source = event as Record<string, unknown>;
96	    const eventType = String(source.type);
97	
98	    if (eventType === "agent_start")
99	    {
100	      const runId = this.NextRunId(context);
101	      this.m_openRuns.add(runId);
102	
103	      return [this.Agui({
104	        type: "RUN_STARTED",
105	        threadId: context.threadId,
106	        runId,
107	      }, context, source)];
108	    }
109	
110	    if (eventType === "agent_end")
111	    {
112	      const runId = [...this.m_openRuns].at(-1) ?? this.RunId(context);
113	      const output = this.CloseOpenForEvent(context, source);
114	      this.m_openRuns.delete(runId);
115	      output.push(this.Agui({
116	        type: "RUN_FINISHED",
117	        threadId: context.threadId,
118	        runId,
119	        result: SanitizeValue(source, { canonicalRoot: context.canonicalRoot }),
120	      }, context, source));
121	      return output;
122	    }
123	
124	    if (eventType === "turn_start")
125	    {
126	      return [this.Agui({ type: "STEP_STARTED", stepName: "pi.turn" }, context, source)];
127	    }
128	
129	    if (eventType === "turn_end")
130	    {
131	      return [this.Agui({ type: "STEP_FINISHED", stepName: "pi.turn" }, context, source)];
132	    }
133	
134	    if (eventType === "message_start")
135	    {
136	      const message = source.message;
137	
138	      if (!IsRecord(message))
139	      {
140	        return this.Fallback(source, context);
141	      }
142	
143	      const messageId = this.PiMessageId(context, message);
144	
145	      if (this.m_openTextMessages.has(messageId))
146	      {
147	        return [];
148	      }
149	
150	      this.m_openTextMessages.add(messageId);
151	
152	      return [this.Agui({
153	        type: "TEXT_MESSAGE_START",
154	        messageId,
155	        role: this.AguiTextRole(message.role),
156	      }, context, source)];
157	    }
158	
159	    if (eventType === "message_update")
160	    {
161	      const message = source.message;
162	      const messageEvent = source.assistantMessageEvent;
163	
164	      if (!IsRecord(message) || !IsRecord(messageEvent))
165	      {
166	        return this.Fallback(source, context);
167	      }
168	
169	      const messageId = this.PiMessageId(context, message);
170	      const deltaType = messageEvent.type;
171	
172	      if (deltaType === "text_delta")
173	      {
174	        return this.AppendText(
175	          context,
176	          messageId,
177	          String(messageEvent.delta ?? ""),
178	          this.AguiTextRole(message.role),
179	          source,
180	        );
181	      }
182	
183	      if (deltaType === "thinking_delta")
184	      {
185	        return this.AppendReasoning(
186	          context,
187	          `${messageId}:thinking`,
188	          String(messageEvent.delta ?? ""),
189	          source,
190	        );
191	      }
192	
193	      if (deltaType === "tool_call_delta")
194	      {
195	        const [toolCallId, toolName] = this.PiToolCallIdentity(context, message, messageEvent);
196	        const output = this.EnsurePiToolStarted(context, toolCallId, toolName, source, messageId);
197	        output.push(this.ToolArgs(context, toolCallId, String(messageEvent.delta ?? ""), source));
198	        return output;
199	      }
200	
201	      return this.Fallback(source, context);
202	    }
203	
204	    if (eventType === "message_end")
205	    {
206	      const message = source.message;
207	
208	      if (!IsRecord(message))
209	      {
210	        return this.Fallback(source, context);
211	      }
212	
213	      const messageId = this.PiMessageId(context, message);
214	      const output = this.CloseReasoning(context, `${messageId}:thinking`, source);
215	      output.push(...this.CloseText(context, messageId, source));
216	      return output;
217	    }
218	
219	    if (eventType === "tool_execution_start")
220	    {
221	      const toolCallId = String(source.toolCallId ?? this.SourceId(context, "pi-tool-exec"));
222	      const toolName = String(source.toolName ?? "pi_tool");
223	      const output = this.EnsurePiToolStarted(context, toolCallId, toolName, source);
224	
225	      if (!this.m_toolsWithArgs.has(toolCallId) && "args" in source)
226	      {
227	        output.push(this.ToolArgs(context, toolCallId, source.args, source));
228	      }
229	
230	      return output;
231	    }
232	
233	    if (eventType === "tool_execution_update")
234	    {
235	      const toolCallId = String(source.toolCallId ?? this.SourceId(context, "pi-tool-exec"));
236	      const toolName = String(source.toolName ?? "pi_tool");
237	      const output = this.EnsurePiToolStarted(context, toolCallId, toolName, source);
238	
239	      if (!this.m_toolsWithArgs.has(toolCallId) && "args" in source)
240	      {
241	        output.push(this.ToolArgs(context, toolCallId, source.args, source));
242	      }
243	
244	      output.push(this.ToolResult(context, toolCallId, source.partialResult, source));
245	      return output;
246	    }
247	
248	    if (eventType === "tool_execution_end")
249	    {
250	      const toolCallId = String(source.toolCallId ?? this.SourceId(context, "pi-tool-exec"));
251	      const toolName = String(source.toolName ?? "pi_tool");
252	      const result = "isError" in source
253	        ? { result: source.result, isError: source.isError }
254	        : source.result;
255	      const output = this.EnsurePiToolStarted(context, toolCallId, toolName, source);
256	      output.push(this.ToolResult(context, toolCallId, result, source));
257	
258	      if (this.m_openTools.has(toolCallId))
259	      {
260	        output.push(this.Agui({ type: "TOOL_CALL_END", toolCallId }, context, source));
261	        this.m_openTools.delete(toolCallId);
262	      }
263	
264	      return output;
265	    }
266	
267	    if (eventType === "auto_retry_end")
268	    {
269	      if (source.success === false)
270	      {
271	        return [this.Agui({
272	          type: "RUN_ERROR",
273	          message: String(source.finalError ?? "Pi auto-retry failed"),
274	          code: "auto_retry_failed",
275	        }, context, source)];
276	      }
277	
278	      return [];
279	    }
280	
281	    if (
282	      eventType === "compaction_start" ||
283	      eventType === "compaction_end" ||
284	      eventType === "auto_retry_start" ||
285	      eventType === "queue_update"
286	    )
287	    {
288	      return [];
289	    }
290	
291	    if (
292	      eventType === "session_info_changed" ||
293	      eventType === "thinking_level_changed" ||
294	      eventType === "thinking_level_change"
295	    )
296	    {
297	      return [this.Agui({
298	        type: "CUSTOM",
299	        name: `pi.${eventType}`,
300	        value: SanitizeValue(source, { canonicalRoot: context.canonicalRoot }),
301	      }, context, source)];
302	    }
303	
304	    if (eventType === "session" || eventType === "model_change" || eventType === "session_info")
305	    {
306	      return [this.Agui({
307	        type: "CUSTOM",
308	        name: `pi.${eventType}`,
309	        value: SanitizeValue(source, { canonicalRoot: context.canonicalRoot }),
310	      }, context, source)];
311	    }
312	
313	    if (eventType === "message" && IsRecord(source.message))
314	    {
315	      const message = source.message;
316	      const messageId = this.PiMessageId(context, message);
317	      const text = ExtractMessageText(message);
318	      const role = this.AguiTextRole(message.role);
319	
320	      return [
321	        this.Agui({ type: "TEXT_MESSAGE_START", messageId, role }, context, source),
322	        this.Agui({ type: "TEXT_MESSAGE_CONTENT", messageId, delta: text }, context, source),
323	        this.Agui({ type: "TEXT_MESSAGE_END", messageId }, context, source),
324	      ];
325	    }
326	
327	    return this.Fallback(source, context);
328	  }
329	
330	  Flush(context: PiMapperContext): AguiEvent[]
331	  {
332	    const output: AguiEvent[] = [];
333	
334	    for (const toolCallId of [...this.m_openTools.keys()].sort())
335	    {
336	      output.push(this.Agui({ type: "TOOL_CALL_END", toolCallId }, context));
337	    }
338	    this.m_openTools.clear();
339	
340	    for (const messageId of [...this.m_openReasoningMessages].sort())
341	    {
342	      output.push(this.Agui({ type: "REASONING_MESSAGE_END", messageId }, context));
343	    }
344	    this.m_openReasoningMessages.clear();
345	
346	    for (const messageId of [...this.m_openReasoningPhases].sort())
347	    {
348	      output.push(this.Agui({ type: "REASONING_END", messageId }, context));
349	    }
350	    this.m_openReasoningPhases.clear();
351	
352	    for (const messageId of [...this.m_openTextMessages].sort())
353	    {
354	      output.push(this.Agui({ type: "TEXT_MESSAGE_END", messageId }, context));
355	    }
356	    this.m_openTextMessages.clear();
357	
358	    for (const runId of [...this.m_openRuns].sort())
359	    {
360	      output.push(this.Agui({
361	        type: "RUN_FINISHED",
362	        threadId: runId,
363	        runId,
364	      }, context));
365	    }
366	    this.m_openRuns.clear();
367	
368	    return output;
369	  }
370	
371	  Fallback(event: PiMappableEvent, context: PiMapperContext): AguiEvent[]
372	  {
373	    const source = structuredClone(event) as Record<string, unknown>;
374	    this.m_fallbackEvents.push(source);
375	
376	    return [
377	      this.Agui({
378	        type: "RAW",
379	        event: this.SanitizeRaw(source, context),
380	        source: String((source.type as string | undefined) ?? "pi"),
381	      }, context, source),
382	    ];
383	  }
384	
385	  Agui(
386	    fields: Record<string, unknown>,
387	    context: PiMapperContext,
388	    sourceEvent?: PiMappableEvent,
389	  ): AguiEvent
390	  {
391	    const event: AguiEvent = { type: String(fields.type) };
392	
393	    for (const [key, value] of Object.entries(fields))
394	    {
395	      if (key === "type" || value === undefined)
396	      {
397	        continue;
398	      }
399	
400	      event[key] = value;
401	    }
402	
403	    if (event.timestamp === undefined && context.timestampMs !== undefined)
404	    {
405	      event.timestamp = context.timestampMs;
406	    }
407	
408	    if (sourceEvent !== undefined)
409	    {
410	      event.rawEvent = this.SanitizeRaw(sourceEvent, context);
411	    }
412	
413	    return event;
414	  }
415	
416	  SanitizeRaw(event: PiMappableEvent, context: PiMapperContext): unknown
417	  {
418	    const options: SanitizeOptions = {};
419	
420	    if (context.canonicalRoot !== undefined)
421	    {
422	      options.canonicalRoot = context.canonicalRoot;
423	    }
424	
425	    return SanitizeValue(event, options);
426	  }
427	
428	  SourceId(context: PiMapperContext, suffix: string): string
429	  {
430	    const step = context.step ?? "unknown";
431	    const sequence = context.sequence ?? "unknown";
432	    return `${context.threadId}:step:${step}:seq:${sequence}:${suffix}`;
433	  }
434	
435	  RunId(context: PiMapperContext): string
436	  {
437	    const step = context.step ?? "unknown";
438	    return `${context.threadId}:step:${step}`;
439	  }
440	
441	  PiMessageId(context: PiMapperContext, message: Record<string, unknown>): string
442	  {
443	    const timestamp = message.timestamp;
444	
445	    if (timestamp !== undefined && timestamp !== null)
446	    {
447	      const role = String(message.role ?? "message");
448	      const step = context.step ?? "unknown";
449	      return `${context.threadId}:step:${step}:pi-message:${role}:${String(timestamp)}`;
450	    }
451	
452	    return this.SourceId(context, "pi-message");
453	  }
454	
455	  AguiTextRole(role: unknown): string
456	  {
457	    const roleValue = String(role ?? "assistant");
458	
459	    if (roleValue === "developer" || roleValue === "system" || roleValue === "assistant" || roleValue === "user")
460	    {
461	      return roleValue;
462	    }
463	
464	    return "assistant";
465	  }
466	
467	  AppendText(
468	    context: PiMapperContext,
469	    messageId: string,
470	    text: string,
471	    role: string,
472	    sourceEvent: PiMappableEvent,
473	  ): AguiEvent[]
474	  {
475	    if (text.length === 0)
476	    {
477	      return [];
478	    }
479	
480	    const output: AguiEvent[] = [];
481	
482	    if (!this.m_openTextMessages.has(messageId))
483	    {
484	      this.m_openTextMessages.add(messageId);
485	      output.push(this.Agui({
486	        type: "TEXT_MESSAGE_START",
487	        messageId,
488	        role,
489	      }, context, sourceEvent));
490	    }
491	
492	    output.push(this.Agui({
493	      type: "TEXT_MESSAGE_CONTENT",
494	      messageId,
495	      delta: text,
496	    }, context, sourceEvent));
497	
498	    return output;
499	  }
500	
501	  CloseText(context: PiMapperContext, messageId: string, sourceEvent: PiMappableEvent): AguiEvent[]
502	  {
503	    if (!this.m_openTextMessages.has(messageId))
504	    {
505	      return [];
506	    }
507	
508	    this.m_openTextMessages.delete(messageId);
509	
510	    return [this.Agui({ type: "TEXT_MESSAGE_END", messageId }, context, sourceEvent)];
511	  }
512	
513	  AppendReasoning(
514	    context: PiMapperContext,
515	    messageId: string,
516	    text: string,
517	    sourceEvent: PiMappableEvent,
518	  ): AguiEvent[]
519	  {
520	    if (text.length === 0)
521	    {
522	      return [];
523	    }
524	
525	    const output: AguiEvent[] = [];
526	
527	    if (!this.m_openReasoningPhases.has(messageId))
528	    {
529	      this.m_openReasoningPhases.add(messageId);
530	      output.push(this.Agui({ type: "REASONING_START", messageId }, context, sourceEvent));
531	    }
532	
533	    if (!this.m_openReasoningMessages.has(messageId))
534	    {
535	      this.m_openReasoningMessages.add(messageId);
536	      output.push(this.Agui({
537	        type: "REASONING_MESSAGE_START",
538	        messageId,
539	        role: "reasoning",
540	      }, context, sourceEvent));
541	    }
542	
543	    output.push(this.Agui({
544	      type: "REASONING_MESSAGE_CONTENT",
545	      messageId,
546	      delta: text,
547	    }, context, sourceEvent));
548	
549	    return output;
550	  }
551	
552	  CloseReasoning(context: PiMapperContext, messageId: string, sourceEvent: PiMappableEvent): AguiEvent[]
553	  {
554	    const output: AguiEvent[] = [];
555	
556	    if (this.m_openReasoningMessages.has(messageId))
557	    {
558	      this.m_openReasoningMessages.delete(messageId);
559	      output.push(this.Agui({ type: "REASONING_MESSAGE_END", messageId }, context, sourceEvent));
560	    }
561	
562	    if (this.m_openReasoningPhases.has(messageId))
563	    {
564	      this.m_openReasoningPhases.delete(messageId);
565	      output.push(this.Agui({ type: "REASONING_END", messageId }, context, sourceEvent));
566	    }
567	
568	    return output;
569	  }
570	
571	  ToolArgs(
572	    context: PiMapperContext,
573	    toolCallId: string,
574	    args: unknown,
575	    sourceEvent: PiMappableEvent,
576	  ): AguiEvent
577	  {
578	    this.m_toolsWithArgs.add(toolCallId);
579	
580	    return this.Agui({
581	      type: "TOOL_CALL_ARGS",
582	      toolCallId,
583	      delta: StringifyPayload(args),
584	    }, context, sourceEvent);
585	  }
586	
587	  ToolResult(
588	    context: PiMapperContext,
589	    toolCallId: string,
590	    content: unknown,
591	    sourceEvent: PiMappableEvent,
592	  ): AguiEvent
593	  {
594	    return this.Agui({
595	      type: "TOOL_CALL_RESULT",
596	      messageId: `${toolCallId}:result`,
597	      toolCallId,
598	      content: StringifyPayload(content),
599	      role: "tool",
600	    }, context, sourceEvent);
601	  }
602	
603	  EnsurePiToolStarted(
604	    context: PiMapperContext,
605	    toolCallId: string,
606	    toolName: string,
607	    sourceEvent: PiMappableEvent,
608	    parentMessageId?: string,
609	  ): AguiEvent[]
610	  {
611	    if (this.m_openTools.has(toolCallId))
612	    {
613	      return [];
614	    }
615	
616	    this.m_openTools.set(toolCallId, {
617	      toolCallId,
618	      toolCallName: toolName,
619	      parentMessageId,
620	    });
621	    this.m_seenTools.add(toolCallId);
622	
623	    const fields: Record<string, unknown> = {
624	      type: "TOOL_CALL_START",
625	      toolCallId,
626	      toolCallName: toolName,
627	    };
628	
629	    if (parentMessageId !== undefined)
630	    {
631	      fields.parentMessageId = parentMessageId;
632	    }
633	
634	    return [this.Agui(fields, context, sourceEvent)];
635	  }
636	
637	  PiToolCallIdentity(
638	    context: PiMapperContext,
639	    message: Record<string, unknown>,
640	    messageEvent: Record<string, unknown>,
641	  ): [string, string]
642	  {
643	    const content = message.content;
644	
645	    if (Array.isArray(content))
646	    {
647	      for (let index = content.length - 1; index >= 0; index -= 1)
648	      {
649	        const block = content[index];
650	
651	        if (IsRecord(block) && block.type === "toolCall")
652	        {
653	          const toolCallId = String(block.id ?? `${this.PiMessageId(context, message)}:tool`);
654	          const toolName = String(messageEvent.name ?? block.name ?? "pi_tool");
655	          return [toolCallId, toolName];
656	        }
657	      }
658	    }
659	
660	    return [
661	      `${this.PiMessageId(context, message)}:tool`,
662	      String(messageEvent.name ?? "pi_tool"),
663	    ];
664	  }
665	
666	  CloseOpenForEvent(context: PiMapperContext, sourceEvent: PiMappableEvent): AguiEvent[]
667	  {
668	    const output: AguiEvent[] = [];
669	
670	    for (const toolCallId of [...this.m_openTools.keys()].sort())
671	    {
672	      output.push(this.Agui({ type: "TOOL_CALL_END", toolCallId }, context, sourceEvent));
673	    }
674	    this.m_openTools.clear();
675	
676	    for (const messageId of [...this.m_openReasoningMessages].sort())
677	    {
678	      output.push(this.Agui({ type: "REASONING_MESSAGE_END", messageId }, context, sourceEvent));
679	    }
680	    this.m_openReasoningMessages.clear();
681	
682	    for (const messageId of [...this.m_openReasoningPhases].sort())
683	    {
684	      output.push(this.Agui({ type: "REASONING_END", messageId }, context, sourceEvent));
685	    }
686	    this.m_openReasoningPhases.clear();
687	
688	    for (const messageId of [...this.m_openTextMessages].sort())
689	    {
690	      output.push(this.Agui({ type: "TEXT_MESSAGE_END", messageId }, context, sourceEvent));
691	    }
692	    this.m_openTextMessages.clear();
693	
694	    return output;
695	  }
696	
697	  NextRunId(context: PiMapperContext): string
698	  {
699	    this.m_runCounter += 1;
700	    return `${this.RunId(context)}:run:${this.m_runCounter}`;
701	  }
702	}
