704	const x_defaultMapper = new PiToAguiMapper();
705	
706	export function mapPiEventToAgui(
707	  event: PiMappableEvent,
708	  context: PiMapperContext,
709	  mapper: PiToAguiMapper = x_defaultMapper,
710	): AguiEvent[]
711	{
712	  return mapper.MapEvent(event, context);
713	}
