715	function ExtractMessageText(message: Record<string, unknown>): string
716	{
717	  const content = message.content;
718	
719	  if (typeof content === "string")
720	  {
721	    return content;
722	  }
723	
724	  if (!Array.isArray(content))
725	  {
726	    return "";
727	  }
728	
729	  const parts: string[] = [];
730	
731	  for (const block of content)
732	  {
733	    if (typeof block === "string")
734	    {
735	      parts.push(block);
736	      continue;
737	    }
738	
739	    if (!IsRecord(block))
740	    {
741	      continue;
742	    }
743	
744	    if (typeof block.text === "string")
745	    {
746	      parts.push(block.text);
747	    }
748	    else if (typeof block.content === "string")
749	    {
750	      parts.push(block.content);
751	    }
752	    else if (typeof block.thinking === "string")
753	    {
754	      parts.push(block.thinking);
755	    }
756	  }
757	
758	  return parts.join("");
759	}
